      <header className="md:hidden fixed top-0 left-0 right-0 h-16 bg-[#050b14]/90 backdrop-blur-md border-b border-violet-900/20 z-40 flex items-center px-4 justify-between">
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsMobileOpen(true)}
            className="p-2 text-violet-300 hover:text-white hover:bg-white/5 rounded-lg transition-colors"
          >
            <Menu size={24} />
          </button>
          <div className="flex items-center gap-2">
             <div className="relative flex items-center justify-center">
                 <Hexagon className="w-8 h-8 text-violet-600 fill-violet-900/20 stroke-[1.5px]" />
                 <span className="absolute font-fantasy font-bold text-xs text-violet-200 tracking-tighter pt-0.5">JD</span>
             </div>
             <span className="font-fantasy font-bold text-lg text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 tracking-widest">
               JUUL-D
             </span>
          </div>
        </div>
      </header>

      {/* Mobile Backdrop Overlay */}
      {isMobileOpen && (
        <div 
          className="fixed inset-0 bg-black/80 backdrop-blur-sm z-40 md:hidden animate-fadeIn"
          onClick={() => setIsMobileOpen(false)}
        />
      )}

      <Sidebar 
        isDesktopCollapsed={isDesktopCollapsed} 
        toggleDesktopSidebar={() => setIsDesktopCollapsed(!isDesktopCollapsed)}
        isMobileOpen={isMobileOpen}
        closeMobileSidebar={() => setIsMobileOpen(false)}
      />

      {/* 
        Main content padding:
        - Mobile: pt-16 (header height), pl-0 (sidebar hidden)
        - Desktop: pt-0, pl-20 (collapsed) or pl-64 (expanded)
      */}
      <main 
        className={`
          min-h-screen relative z-10 transition-all duration-300 ease-in-out
          pt-16 px-4 md:px-6 md:pt-8 md:pb-8
          md:pl-20 
          ${isDesktopCollapsed ? '' : 'md:pl-64'}
        `}
      >
        <div className="container mx-auto">
           <Outlet />
        </div>
      </main>
    </div>
  );
};

import React from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { LayoutGrid, Users, Sword, Library, LogOut, Hexagon, ChevronLeft, ChevronRight, X } from 'lucide-react';
import { NavItem } from '../../types';

interface SidebarProps {
  isDesktopCollapsed: boolean;
  toggleDesktopSidebar: () => void;
  isMobileOpen: boolean;
  closeMobileSidebar: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  isDesktopCollapsed, 
  toggleDesktopSidebar,
  isMobileOpen,
  closeMobileSidebar
}) => {
  const { signOut, user } = useAuth();
  const navigate = useNavigate();

  const navItems: NavItem[] = [
    { label: 'Hub', path: '/', icon: LayoutGrid },
    { label: 'Roster', path: '/roster', icon: Users },
    { label: 'Simulation', path: '/battle', icon: Sword },
    { label: 'Archives', path: '/lore', icon: Library },
  ];

  const handleLogout = async () => {
    await signOut();
    navigate('/auth');
    if (window.innerWidth < 768) closeMobileSidebar();
  };

  const handleLinkClick = () => {
    if (window.innerWidth < 768) closeMobileSidebar();
  }

  return (
    <aside 
      className={`
        fixed inset-y-0 left-0 z-50
        bg-[#050b14]/95 backdrop-blur-md border-r border-violet-900/20 
        flex flex-col transition-transform duration-300 ease-in-out
        w-64 md:w-64
        ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'} 
        md:translate-x-0
        ${isDesktopCollapsed ? 'md:w-20' : ''}
      `}
    >
      {/* Mobile Close Button */}
      <button 
        onClick={closeMobileSidebar}
        className="md:hidden absolute top-4 right-4 text-slate-400 hover:text-white"
      >
        <X size={24} />
      </button>

      {/* Desktop Toggle Button */}
      <button 
        onClick={toggleDesktopSidebar}
        className="hidden md:flex absolute -right-3 top-24 bg-slate-900 border border-violet-500/50 text-violet-300 rounded-full p-1 shadow-[0_0_10px_rgba(139,92,246,0.3)] hover:text-white hover:scale-110 transition-all z-50"
      >
        {isDesktopCollapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
      </button>

      {/* Header / Logo */}
      <div className="h-24 flex items-center justify-center border-b border-violet-900/20 overflow-hidden shrink-0">

        {/* LOGO CONTAINER */}
        <div className="flex items-center gap-3">
           {/* Icon: Always visible */}
           <div className={`relative flex items-center justify-center group transition-all duration-300 ${isDesktopCollapsed ? 'scale-110' : ''}`}>
             <Hexagon className="w-10 h-10 text-violet-600 fill-violet-900/20 stroke-[1.5px] group-hover:stroke-violet-400 transition-colors" />
             <span className="absolute font-fantasy font-bold text-sm text-violet-200 tracking-tighter pt-0.5 group-hover:text-white transition-colors">JD</span>
           </div>

           {/* Text: Hidden when desktop collapsed */}
           <h1 
             className={`
               font-fantasy text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 tracking-widest transition-all duration-300 origin-left
               ${isDesktopCollapsed ? 'w-0 opacity-0 scale-0 hidden md:block' : 'w-auto opacity-100 scale-100'}
             `}
           >
             JUUL-D
           </h1>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 py-8 flex flex-col gap-2 px-3 overflow-y-auto custom-scrollbar">
        {navItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            onClick={handleLinkClick}
            className={({ isActive }) => `
              group flex items-center gap-4 px-3 py-3 rounded-lg transition-all duration-300 overflow-hidden relative
              ${isActive 
                ? 'bg-violet-900/20 text-violet-200 border border-violet-500/30 shadow-[0_0_10px_rgba(139,92,246,0.1)]' 
                : 'text-slate-400 hover:bg-white/5 hover:text-violet-300'
              }
              ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title={isDesktopCollapsed ? item.label : ''}
          >
            {({ isActive }) => (
              <>
                <item.icon 
                  className={`
                    min-w-[24px] w-6 h-6 transition-all duration-300 shrink-0
                    ${isActive ? 'drop-shadow-[0_0_5px_rgba(139,92,246,0.5)]' : ''}
                  `} 
                />

                <span 
                  className={`
                    font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300
                    ${isDesktopCollapsed ? 'opacity-0 w-0 md:hidden' : 'opacity-100 w-auto'}
                  `}
                >
                  {item.label}
                </span>
              </>
            )}
          </NavLink>
        ))}
      </nav>

      {/* User Footer */}
      <div className="p-4 border-t border-violet-900/20 shrink-0">
        <div className="flex flex-col gap-2">
          {user && !isDesktopCollapsed && (
            <div className="flex flex-col mb-2 px-2 animate-fadeIn">
              <span className="text-xs text-slate-500 uppercase font-bold">Logged in as</span>
              <span className="text-sm text-violet-300 truncate font-mono">{user.email}</span>
            </div>
          )}

          <button 
            onClick={handleLogout}
            className={`
              flex items-center gap-4 px-3 py-2 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-900/10 transition-colors w-full
              ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title="Logout"
          >
            <LogOut className="w-5 h-5 min-w-[20px] shrink-0" />
            <span 
              className={`
                font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300
                ${isDesktopCollapsed ? 'opacity-0 w-0 md:hidden' : 'opacity-100 w-auto'}
              `}
            >
              Logout
            </span>
          </button>
        </div>
      </div>
    </aside>
  );
};
